-- Name: ayuda_solicitud; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ayuda_solicitud (
    id bigint NOT NULL,
    solicitante_practicante_id integer NOT NULL,
    helper_practicante_id integer,
    descripcion text NOT NULL,
    canal_voz_url character varying(500),
    canal_voz_nombre character varying(100),
    estado character varying(20) DEFAULT 'PENDIENTE'::character varying NOT NULL,
    valoracion smallint,
    mensaje_discord_id bigint,
    canal_discord_id bigint,
    feedback_dm_enviado boolean DEFAULT false NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    aceptado_at timestamp without time zone,
    valorado_at timestamp without time zone,
    finalizado_at timestamp without time zone,
    notificacion_enviada boolean DEFAULT false NOT NULL,
    notificacion_at timestamp without time zone,
    CONSTRAINT chk_ayuda_estado CHECK (((estado)::text = ANY (ARRAY[('PENDIENTE'::character varying)::text, ('EN_CURSO'::character varying)::text, ('FINALIZADA'::character varying)::text, ('CANCELADA'::character varying)::text, ('EXPIRADA'::character varying)::text]))),
    CONSTRAINT chk_ayuda_valoracion CHECK (((valoracion IS NULL) OR ((valoracion >= 1) AND (valoracion <= 5))))
);


