CREATE TABLE public.bot_admin (
    discord_id bigint NOT NULL,
    nombre_discord character varying(255),
    rol character varying(100) DEFAULT 'Developer'::character varying,
    email character varying(255),
    password_hash character varying(255),
    reset_token_hash character varying(64),
    reset_token_expires_at timestamp(6) without time zone,
    reset_requested_at timestamp(6) without time zone,
    session_version integer DEFAULT 0 NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    CONSTRAINT bot_admin_credentials_pair_check CHECK (((email IS NULL) = (password_hash IS NULL))),
    CONSTRAINT bot_admin_email_normalized_check CHECK (((email IS NULL) OR ((email)::text = lower(btrim((email)::text)))))
);


