    updated_by bigint,
    intento smallint DEFAULT 1 NOT NULL,
    pr_url character varying(500),
    CONSTRAINT capacitacion_progreso_check CHECK (((fecha_fin IS NULL) OR (fecha_inicio IS NULL) OR (fecha_fin >= fecha_inicio))),
    CONSTRAINT capacitacion_progreso_intento_check CHECK (((intento >= 1) AND (intento <= 3)))
);


