--
-- Name: vw_horas_totales_practicante; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_horas_totales_practicante AS
 WITH horas_asistencia AS (
         SELECT a.practicante_id,
            date_trunc('second'::text, COALESCE(sum((a.hora_salida - a.hora_entrada)), '00:00:00'::interval)) AS horas_asistencia
           FROM public.asistencia a
          WHERE ((a.hora_entrada IS NOT NULL) AND (a.hora_salida IS NOT NULL))
          GROUP BY a.practicante_id
        ), horas_recuperacion AS (
         SELECT r.practicante_id,
            date_trunc('second'::text, COALESCE(sum((r.hora_salida - r.hora_entrada)), '00:00:00'::interval)) AS horas_recuperacion
           FROM public.recuperacion r
          WHERE ((r.hora_entrada IS NOT NULL) AND (r.hora_salida IS NOT NULL) AND ((r.estado)::text = 'valido'::text))
          GROUP BY r.practicante_id
        )
 SELECT p.id AS practicante_id,
    p.id_discord,
    p.nombre_completo,
    p.rol,
    p.fecha_inscripcion,
    date_trunc('second'::text, COALESCE(p.horas_base, '00:00:00'::interval)) AS horas_base,
    date_trunc('second'::text, COALESCE(ha.horas_asistencia, '00:00:00'::interval)) AS horas_asistencia,
    date_trunc('second'::text, COALESCE(hr.horas_recuperacion, '00:00:00'::interval)) AS horas_recuperacion,
    date_trunc('second'::text, ((COALESCE(p.horas_base, '00:00:00'::interval) + COALESCE(ha.horas_asistencia, '00:00:00'::interval)) + COALESCE(hr.horas_recuperacion, '00:00:00'::interval))) AS horas_totales
   FROM ((public.practicante p
     LEFT JOIN horas_asistencia ha ON ((ha.practicante_id = p.id)))
     LEFT JOIN horas_recuperacion hr ON ((hr.practicante_id = p.id)))
  WHERE ((p.estado)::text = 'activo'::text);


